import { describe, it, expect } from 'vitest';
import { render } from '@testing-library/react';
import type { ComponentType } from 'react';
import * as routes from '@/routes';
import AlmacenIndex from '@/pages/almacen/index';
import InicioIndex from '@/pages/inicio/index';

// Every GET route generated by Wayfinder from routes/web.php
const KNOWN_URLS = new Set(
    Object.values(routes)
        .filter(
            (r): r is typeof routes.inicio =>
                typeof r === 'function' && 'definition' in r,
        )
        .filter((r) => r.definition.methods.includes('get'))
        .map((r) => r.definition.url),
);

function internalHrefs(Page: ComponentType): string[] {
    const { container } = render(<Page />);

    return Array.from(container.querySelectorAll('a[href^="/"]')).map(
        (a) => new URL(a.getAttribute('href')!, 'http://x').pathname,
    );
}

describe('page links', () => {
    it.each([
        ['inicio', InicioIndex],
        ['almacen', AlmacenIndex],
    ])('%s only links to existing routes', (_, Page) => {
        const hrefs = internalHrefs(Page);

        expect(hrefs.length).toBeGreaterThan(0);
        expect(hrefs.filter((href) => !KNOWN_URLS.has(href))).toEqual([]);
    });

    it('inicio quick actions point to facturacion and laboratorio', () => {
        const hrefs = internalHrefs(InicioIndex);

        expect(hrefs).toContain('/facturacion');
        expect(hrefs).toContain('/laboratorio');
    });

    it('almacen links to entrada de mercancia', () => {
        expect(internalHrefs(AlmacenIndex)).toContain('/entrada-mercancia');
    });
});
